pub fn run_splash() {
    print!("\x1b[2J\x1b[1;1H"); // Clear screen
    
    println!("\n\n\n\n\n");

    // Print the clean Jules Octopus Logo
    for line in SPLASH_LOGO.lines() {
        // Center the logo
        println!("                         {}", line);
    }
    
    // Animate the loading spinner ("Windows style")
    let spinner = ['|', '/', '-', '\\'];
    let mut i = 0;
    
    print!("\x1b[?25l"); // Hide cursor
    for _ in 0..40 { // Spin for 4 seconds (100ms * 40)
        print!("\r                                   {CYAN}{BOLD}[ {} ] Booting Jules AI Agent...{RESET}", spinner[i]);
        let _ = io::stdout().flush();
        i = (i + 1) % spinner.len();
        thread::sleep(Duration::from_millis(100));
    }
    print!("\x1b[?25h"); // Show cursor
    println!("\n");
}
